// The PLCPacketList schema every datatroniq topic on this estate is encoded with.
// Keep this text and the `protobuf-file` config node's protopath in step.
const data = `syntax = "proto3";

package datatron;

option go_package = "/internal/protobuf";

message PLCPacket {
  string uuid = 1;
  int32 sequence_number = 2;

  uint64 sys_time = 3;
  uint64 plc_time = 4;


  oneof measured_value {
    sint64 value_integer = 5;
    string value_string = 6;
    double value_double = 7;
    bool value_bool = 8;
    bytes value_bytes = 9;
  }

  bool is_delta = 10;
}


message PLCPacketList {
  repeated PLCPacket plc_packets = 1;
}`

// Set BOTH: the file node takes msg.filename, the payload is what gets written.
msg.filename = flow.get('protoPath');
if (!msg.filename) {
    node.error('protoPath not set - check the Set flow config node', msg);
    return null;
}
msg.payload = data;

return msg;

return {
    payload: msg.payload,
    filepath: msg.filename,
    debugInfo: "Protobuf file configured/changed"
};
